## Structs, enums and traits

```rust-norun
#[derive(Debug, Clone, PartialEq)]
struct Point { x: f64, y: f64 }

impl Point {
    fn new(x: f64, y: f64) -> Self { Point { x, y } }
    fn dist(&self, other: &Point) -> f64 { ((self.x - other.x).powi(2) + (self.y - other.y).powi(2)).sqrt() }
    fn shift(&mut self, dx: f64) { self.x += dx; }
}

enum Shape { Circle(f64), Rect { w: f64, h: f64 } }

trait Area { fn area(&self) -> f64; fn describe(&self) -> String { format!("area {:.1}", self.area()) } }

impl Area for Shape {
    fn area(&self) -> f64 {
        match self { Shape::Circle(r) => 3.14159 * r * r, Shape::Rect { w, h } => w * h }
    }
}

impl std::fmt::Display for Point {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result { write!(f, "({}, {})", self.x, self.y) }
}

fn largest<T: PartialOrd + Copy>(items: &[T]) -> T { /* ... */ items[0] }
fn total(shapes: &[Box<dyn Area>]) -> f64 { shapes.iter().map(|s| s.area()).sum() }
```

## Option and Result

| Code | Meaning |
|---|---|
| `if let Some(x) = opt { }`, `let Some(x) = opt else { return; };` | Use the value if it is there |
| `opt.unwrap_or(0)`, `unwrap_or_default()`, `unwrap_or_else(\|\| ...)` | A default instead |
| `opt.map(\|x\| x * 2)`, `and_then`, `filter`, `ok_or("missing")` | Transform |
| `res?` | Return the error early (converted with `From`) |
| `res.map_err(\|e\| e.to_string())`, `res.ok()`, `res.is_ok()` | Convert |
| `fn main() -> Result<(), Box<dyn std::error::Error>>` | Let `main` use `?` |

